{
  "paths": {},
  "components": {
    "schemas": {
      "Customer": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "고객 ID (예: C001)"
          },
          "name": {
            "type": "string",
            "description": "이름"
          },
          "email": {
            "type": "string",
            "description": "이메일"
          },
          "phone": {
            "type": "string",
            "description": "휴대폰 번호"
          },
          "address": {
            "type": "string",
            "description": "배송지 주소"
          },
          "birth_date": {
            "type": "string",
            "description": "생년월일 (YYYY-MM-DD)"
          },
          "tier": {
            "type": "string",
            "enum": [
              "gold",
              "silver",
              "bronze"
            ],
            "description": "회원 등급"
          },
          "points": {
            "type": "integer",
            "description": "적립 포인트"
          },
          "order": {
            "type": "object",
            "description": "가장 최근 주문",
            "properties": {
              "order_id": {
                "type": "string",
                "description": "주문 번호"
              },
              "item": {
                "type": "string",
                "description": "상품명"
              },
              "status": {
                "type": "string",
                "enum": [
                  "preparing",
                  "shipped",
                  "in_transit",
                  "delivered",
                  "delayed",
                  "returned"
                ],
                "description": "배송 상태"
              },
              "carrier": {
                "type": "string",
                "description": "택배사"
              },
              "eta": {
                "type": "string",
                "description": "도착 예정일 (YYYY-MM-DD)"
              }
            }
          },
          "card_number": {
            "type": "string",
            "description": "결제 카드 번호"
          },
          "health_note": {
            "type": [
              "string",
              "null"
            ],
            "description": "건강 관련 배송 메모"
          }
        }
      },
      "Contact": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "연락처 ID (예: P001)"
          },
          "name": {
            "type": "string",
            "description": "이름"
          },
          "company": {
            "type": "string",
            "description": "회사"
          },
          "title": {
            "type": "string",
            "description": "직함"
          },
          "email": {
            "type": "string",
            "description": "업무 이메일"
          },
          "mobile": {
            "type": "string",
            "description": "휴대폰 번호"
          },
          "home_address": {
            "type": "string",
            "description": "자택 주소"
          },
          "birthday": {
            "type": "string",
            "description": "생일 (YYYY-MM-DD)"
          },
          "passport_no": {
            "type": "string",
            "description": "여권 번호 (출장 예약용)"
          }
        }
      },
      "Mail": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "메일 ID (예: M001)"
          },
          "from_name": {
            "type": "string",
            "description": "보낸 사람 이름"
          },
          "from_email": {
            "type": "string",
            "description": "보낸 사람 이메일"
          },
          "customer_id": {
            "type": [
              "string",
              "null"
            ],
            "description": "보낸 사람이 고객이면 고객 ID"
          },
          "contact_id": {
            "type": [
              "string",
              "null"
            ],
            "description": "보낸 사람이 거래처면 연락처 ID"
          },
          "subject": {
            "type": "string",
            "description": "제목"
          },
          "label": {
            "type": "string",
            "enum": [
              "inquiry",
              "refund",
              "complaint",
              "shipping",
              "partnership"
            ],
            "description": "분류"
          },
          "received_at": {
            "type": "string",
            "description": "받은 시각 (ISO 8601)"
          },
          "body": {
            "type": "string",
            "description": "본문"
          }
        }
      }
    }
  }
}

